(function(){'use strict';document.addEventListener('DOMContentLoaded',function(){const mobileMenuBtn=document.getElementById('mobileMenuBtn');const mainNav=document.getElementById('mainNav');const navOverlay=document.getElementById('navOverlay');if(mobileMenuBtn&&mainNav&&navOverlay){function closeNav(){mainNav.classList.remove('active');navOverlay.classList.remove('active');const icon=mobileMenuBtn.querySelector('i');if(icon)icon.className='fa-solid fa-bars';document.body.style.overflow='';}mobileMenuBtn.addEventListener('click',function(){const isOpen=mainNav.classList.toggle('active');navOverlay.classList.toggle('active',isOpen);const icon=mobileMenuBtn.querySelector('i');if(icon)icon.className=isOpen?'fa-solid fa-xmark':'fa-solid fa-bars';document.body.style.overflow=isOpen?'hidden':'';});navOverlay.addEventListener('click',closeNav);const navLinks=mainNav.querySelectorAll('a');navLinks.forEach(function(link){link.addEventListener('click',closeNav);});}const sliders=document.querySelectorAll('.package-slider');const isAr=document.documentElement.lang!=='en';sliders.forEach(function(slider){const slides=slider.querySelectorAll('.slide');if(slides.length<=1){const counter=document.createElement('div');counter.className='slider-counter';counter.textContent='1/1';slider.appendChild(counter);return;}function ensureSlideLoaded(slide){if(!slide)return;const dataSrc=slide.getAttribute('data-src');if(dataSrc&&slide.getAttribute('src')!==dataSrc){slide.setAttribute('src',dataSrc);slide.removeAttribute('data-src');}}const prevBtn=document.createElement('button');prevBtn.type='button';prevBtn.className='slider-btn prev-btn';prevBtn.setAttribute('aria-label',isAr?'الصورة السابقة':'Previous slide');prevBtn.innerHTML='<i class="fa-solid fa-chevron-left" aria-hidden="true"></i><span class="sr-only">'+(isAr?'السابق':'Previous')+'</span>';const nextBtn=document.createElement('button');nextBtn.type='button';nextBtn.className='slider-btn next-btn';nextBtn.setAttribute('aria-label',isAr?'الصورة التالية':'Next slide');nextBtn.innerHTML='<i class="fa-solid fa-chevron-right" aria-hidden="true"></i><span class="sr-only">'+(isAr?'التالي':'Next')+'</span>';const counter=document.createElement('div');counter.className='slider-counter';slider.appendChild(prevBtn);slider.appendChild(nextBtn);slider.appendChild(counter);let currentSlide=0;function updateSlides(){slides.forEach(function(slide,idx){if(idx===currentSlide){ensureSlideLoaded(slide);slide.classList.add('active');}else{slide.classList.remove('active');}});counter.textContent=(currentSlide+1)+'/'+slides.length;const nextIdx=(currentSlide+1)%slides.length;const prevIdx=(currentSlide-1+slides.length)%slides.length;ensureSlideLoaded(slides[nextIdx]);ensureSlideLoaded(slides[prevIdx]);}function nextSlide(){currentSlide=(currentSlide+1)%slides.length;updateSlides();}function prevSlide(){currentSlide=(currentSlide-1+slides.length)%slides.length;updateSlides();}nextBtn.addEventListener('click',nextSlide);prevBtn.addEventListener('click',prevSlide);slider.addEventListener('pointerenter',function(){ensureSlideLoaded(slides[1]);},{once:true});let touchStartX=0;let touchStartY=0;slider.addEventListener('touchstart',function(e){if(e.touches&&e.touches.length>0){touchStartX=e.touches[0].clientX;touchStartY=e.touches[0].clientY;}},{passive:true});slider.addEventListener('touchend',function(e){if(e.changedTouches&&e.changedTouches.length>0){const diffX=e.changedTouches[0].clientX-touchStartX;const diffY=e.changedTouches[0].clientY-touchStartY;if(Math.abs(diffX)>35&&Math.abs(diffX)>Math.abs(diffY)){if(diffX<0)nextSlide();else prevSlide();}}},{passive:true});counter.textContent='1/'+slides.length;if('requestIdleCallback' in window){window.requestIdleCallback(function(){ensureSlideLoaded(slides[1]);},{timeout:3000});}});const shareBtns=document.querySelectorAll('.btn-share');shareBtns.forEach(function(btn){btn.addEventListener('click',function(e){e.preventDefault();const shareData={title:document.title,text:document.querySelector('.detail-desc')?document.querySelector('.detail-desc').textContent:document.title,url:window.location.href};if(navigator.share){navigator.share(shareData).catch(function(){});}else if(navigator.clipboard){navigator.clipboard.writeText(window.location.href).then(function(){const originalText=btn.innerHTML;btn.innerHTML='<i class="fa-solid fa-check"></i>'+(isAr?'تم نسخ الرابط!':'Link Copied!');setTimeout(function(){btn.innerHTML=originalText;},2500);});}});});});window.toggleExpand=function(btn){const block=btn.closest('.expandable-block');if(!block)return;const isExpanded=block.classList.toggle('expanded');const isAr=document.documentElement.lang!=='en';const textSpan=btn.querySelector('.toggle-text');if(textSpan){textSpan.textContent=isExpanded?(isAr?'عرض أقل':'Show Less'):(isAr?'عرض المزيد':'Show More');}};})();